export default function Receipt({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const print = p.print ?? 0;
  const check = p.check ?? 0;
  const h = 60 + 100 * print; // paper height
  const top = 24;
  const bot = top + h;
  const zig = (y: number) => {
    let d = `L142 ${y}`;
    for (let i = 0; i < 6; i++) {
      const x1 = 142 - i * 14 - 7;
      const x2 = 142 - (i + 1) * 14;
      d += ` L${x1} ${y + 7} L${x2} ${y}`;
    }
    return d;
  };
  const line = (y: number, w: number, k: number) => {
    const t = Math.max(0, Math.min(1, (print * 100 - (y - 50)) / 14));
    return (
      <g opacity={t}>
        <path d={`M62 ${y} L${62 + w} ${y}`} stroke={c.primary} strokeWidth={sw} />
        <path d={`M126 ${y} L138 ${y}`} stroke={c.primary} strokeWidth={sw} />
      </g>
    );
  };
  const tt = Math.max(0, Math.min(1, (print - 0.7) / 0.3));
  return (
    <g strokeLinecap="round" strokeLinejoin="round" fill="none">
      <ellipse cx={100} cy={188} rx={50} ry={5} fill={c.black} opacity={0.1} />
      <rect x={50} y={14} width={92} height={10} rx={5} fill={c.surface2} stroke={c.primary} strokeWidth={sw} />
      <path d={`M58 ${top} L58 ${bot} ${zig(bot).replace('L142', 'L142')}`.replace(`L58 ${bot} L142 ${bot}`, `L58 ${bot} L142 ${bot}`)} fill="none" />
      <path d={`M58 ${top} L142 ${top} L142 ${bot} L58 ${bot} Z`} fill={c.surface} stroke={c.primary} strokeWidth={sw} />
      <path d="M70 40 L130 40" stroke={c.primary} strokeWidth={sw} />
      {line(62, 36, 0)}
      {line(80, 28, 1)}
      {line(98, 40, 2)}
      {line(116, 24, 3)}
      <g opacity={tt}>
        <path d="M62 130 L138 130" stroke={c.primary} strokeWidth={sw} strokeDasharray="2 6" />
        <path d="M62 146 L90 146" stroke={c.primary} strokeWidth={sw} />
        <rect x={108} y={138} width={30} height={16} rx={4} stroke={c.primary} strokeWidth={sw} />
      </g>
      <circle cx={146} cy={bot - 4} r={0} />
      <g transform={`translate(0 ${bot - 184})`}>
        <circle cx={100} cy={160} r={4 + 10 * check} fill={c.accent} fillOpacity={0.3 * check} stroke={c.accent} strokeWidth={sw} />
        <path d="M93 160 L99 166 L109 154" stroke={c.primary} strokeWidth={sw} strokeDasharray="24" strokeDashoffset={24 * (1 - check)} opacity={check > 0.01 ? 1 : 0} />
      </g>
    </g>
  );
}

