export default function ParcelBox({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const lid = p.lid ?? 0;
  const open = (1 - lid) * 60;
  const tape = Math.max(0, (lid - 0.6) / 0.4);
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <defs>
        <linearGradient id={`${uid}-g1`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor={c.gradA} />
          <stop offset="1" stopColor={c.gradB} />
        </linearGradient>
      </defs>
      <ellipse cx={100} cy={172} rx={70} ry={8} fill={c.black} opacity={0.12} />
      {/* back flap */}
      <rect x={43} y={Math.round(60 + open * 0.3)} width={114} height={26} rx={8} fill={c.black} opacity={0.18} />
      <rect x={40} y={Math.round(57 + open * 0.3)} width={114 + 6} height={26} rx={8} fill={c.primary} opacity={0.7} />
      {/* body */}
      <rect x={43} y={84} width={118} height={86} rx={12} fill={c.black} opacity={0.18} />
      <rect x={40} y={81} width={120} height={86} rx={12} fill={`url(#${uid}-g1)`} />
      <rect x={52} y={140} width={34} height={6} rx={3} fill={c.onPrimary} opacity={0.6} />
      <rect x={52} y={152} width={22} height={6} rx={3} fill={c.onPrimary} opacity={0.4} />
      {/* front lid */}
      <g transform={`translate(0 ${81 - open * 0.2}) scale(1 ${1 - open / 90}) translate(0 -81)`}>
        <rect x={36} y={74} width={130} height={20} rx={9} fill={c.black} opacity={0.18} />
        <rect x={33} y={71} width={130} height={20} rx={9} fill={c.primary} />
      </g>
      {/* tape */}
      <rect x={90} y={71} width={20} height={Math.max(0.01, 70 * tape + 20 * (lid > 0.6 ? 1 : 0))} rx={5} fill={c.black} opacity={lid > 0.6 ? 0.18 : 0} transform="translate(3 3)" />
      <rect x={90} y={71} width={20} height={Math.max(0.01, 70 * tape + 20 * (lid > 0.6 ? 1 : 0))} rx={5} fill={c.accent} opacity={lid > 0.6 ? 1 : 0} />
    </g>
  );
}

