export default function DeliveryTruck({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const w = p.wheels ?? 0;
  const dx = w * 16;
  const spin = w * 720;
  const sh = { fill: c.black, opacity: 0.18 } as const;
  const wheel = (cx: number) => (
    <g>
      <circle cx={cx + 3} cy={153} r={15} {...sh} />
      <circle cx={cx} cy={150} r={15} fill={c.text} />
