export default function StatsChart({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const b = p.bars ?? 0;
  const base = 160;
  const hs = [30, 52, 42, 72, 96];
  const bars = hs.map((h, i) => {
    const hh = Math.max(6, h * b);
    return { x: 50 + i * 24, y: base - hh, h: hh };
  });
  const pts = bars.map((r) => `${r.x + 9} ${r.y - 12}`);
  const line = "M" + pts.join(" L");
  const last = bars[4];
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <defs>
        <linearGradient id={`${uid}-g1`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor={c.gradA} />
          <stop offset="1" stopColor={c.gradB} />
        </linearGradient>
      </defs>
      <rect x={23} y={33} width={154} height={140} rx={18} fill={c.black} opacity={0.18} />
      <rect x={20} y={30} width={154} height={140} rx={18} fill={c.surface} />
      <rect x={33} y={46} width={108} height={7} rx={3.5} fill={c.black} opacity={0.18} />
      <rect x={31} y={44} width={108} height={7} rx={3.5} fill={c.surface2} />
      <rect x={31} y={60} width={60} height={6} rx={3} fill={c.surface2} />
      {bars.map((r, i) => (
        <g key={i}>
          <rect x={r.x + 3} y={r.y + 3} width={18} height={r.h} rx={7} fill={c.black} opacity={0.18} />
          <rect x={r.x} y={r.y} width={18} height={r.h} rx={7} fill={i === 4 ? `url(#${uid}-g1)` : c.primary} opacity={i === 4 ? 1 : 0.55 + i * 0.1} />
        </g>
      ))}
      <path d={line} fill="none" stroke={c.black} strokeWidth={sw} opacity={0.18} transform="translate(3 3)" />
      <path d={line} fill="none" stroke={c.accent} strokeWidth={sw} />
      <circle cx={last.x + 12} cy={last.y - 9} r={8} fill={c.black} opacity={0.18} />
      <circle cx={last.x + 9} cy={last.y - 12} r={8} fill={c.accent} />
      <circle cx={last.x + 9} cy={last.y - 12} r={3} fill={c.onPrimary} />
    </g>
  );
}

