export default function EmptyStorefront({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const sh = p.shutter ?? 0;
  const sv = p.shelves ?? 0;
  // iso: x axis goes right-down (0.866,0.5), y axis goes left-down (-0.866,0.5)
  // box corners: front corner at (100,170), height 80
  // left face (shop front, facing left-down): from (100,170) to (40,135)
  // right face from (100,170) to (160,135)
  const H = 80;
  const lx = 40, rx = 160;
  const doorTop = 66 + sh * 0; 
  const open = sh * 54; // opening height
  const prods = [c.accent, c.primary, c.gradA, c.gradB];
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <path d="M100 190 L172 148 L100 106 L28 148 Z" fill={c.black} opacity={0.1} />
      {/* right face */}
      <path d="M100 170 L160 135 L160 65 L100 100 Z" fill={c.primary} fillOpacity={0.5} stroke={c.border} strokeWidth={sw} />
      {/* left face */}
      <path d="M100 170 L40 135 L40 65 L100 100 Z" fill={c.primary} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
      {/* top */}
      <path d="M100 100 L160 65 L100 30 L40 65 Z" fill={c.primary} fillOpacity={1} stroke={c.border} strokeWidth={sw} />
      {/* opening on left face */}
      <path d="M52 128 L88 149 L88 99 L52 78 Z" fill={c.bg2} stroke={c.border} strokeWidth={sw} />
      {/* shelves inside */}
      {[0, 1, 2].map(i => {
        const y = 94 + i * 17;
        return (
          <g key={i}>
            <path d={`M54 ${y - 6 + 0} L86 ${y + 12} L86 ${y + 15} L54 ${y - 3} Z`} fill={c.surface} stroke={c.border} strokeWidth={sw} />
            {[0, 1, 2].map(j => {
              const x = 59 + j * 10;
              const yy = y - 3 + j * 5.8;
              return <path key={j} d={`M${x} ${yy} l0 ${-8 * sv} l7 4 l0 ${8 * sv} Z`} fill={prods[(i + j) % 4]} fillOpacity={0.9} stroke={c.border} strokeWidth={sw} opacity={sv > 0.02 ? 1 : 0} />;
            })}
          </g>
        );
      })}
      {/* shutter */}
      <path d={`M52 ${78} L88 ${99} L88 ${99 + (50 - open) } L52 ${78 + (50 - open)} Z`} fill={c.surface2} stroke={c.border} strokeWidth={sw} opacity={sh < 0.98 ? 1 : 0} />
      {[1, 2, 3, 4, 5].map(k => {
        const d = k * 8;
        return d < 50 - open ? <path key={k} d={`M52 ${78 + d} L88 ${99 + d}`} stroke={c.border} strokeWidth={sw} opacity={0.6} /> : null;
      })}
      {/* shutter box */}
      <path d="M50 77 L88 99 L88 94 L50 72 Z" fill={c.surface} stroke={c.border} strokeWidth={sw} />
      {/* awning */}
      <path d="M100 108 L100 98 L36 61 L36 71 Z" fill={c.accent} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
      <path d="M36 71 L100 108 L112 112 L46 74 Z" fill={c.accent} fillOpacity={1} stroke={c.border} strokeWidth={sw} />
      <path d="M46 74 L112 112 L112 118 L46 80 Z" fill={c.accent} fillOpacity={0.5} stroke={c.border} strokeWidth={sw} />
      {/* sign on right face */}
      <path d="M112 106 L148 85 M112 116 L134 103" stroke={c.onPrimary} strokeWidth={sw} opacity={0.8} />
    </g>
  );
}

