export default function ProductBlocks({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const t = p.boxes ?? 0;
  const k = 0.866, h = 0.5;
  const ease = (x: number) => Math.min(1, Math.max(0, x));
  const box = (x: number, y: number, w: number, d: number, ht: number, col: string, key: string) => {
    const a = w * k, b = d * k;
    const top = `M${x} ${y - ht} L${x + a} ${y - ht + w * h} L${x + a - b} ${y - ht + w * h + d * h} L${x - b} ${y - ht + d * h} Z`;
    const left = `M${x - b} ${y - ht + d * h} L${x + a - b} ${y - ht + w * h + d * h} L${x + a - b} ${y + w * h + d * h} L${x - b} ${y + d * h} Z`;
    const right = `M${x + a} ${y - ht + w * h} L${x + a - b} ${y - ht + w * h + d * h} L${x + a - b} ${y + w * h + d * h} L${x + a} ${y + w * h} Z`;
    return (
      <g key={key}>
        <path d={left} fill={col} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
        <path d={right} fill={col} fillOpacity={0.5} stroke={c.border} strokeWidth={sw} />
        <path d={top} fill={col} fillOpacity={1} stroke={c.border} strokeWidth={sw} />
      </g>
    );
  };
  const d1 = ease(t / 0.4), d2 = ease((t - 0.25) / 0.4), d3 = ease((t - 0.5) / 0.4);
  const drop = (d: number) => -(1 - d) * (1 - d) * 60;
  const fall = (d: number) => (d <= 0 ? -60 : drop(d));
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <path d="M100 176 L172 134 L100 92 L28 134 Z" fill={c.surface} stroke={c.border} strokeWidth={sw} />
      <path d="M28 134 L28 142 L100 184 L100 176 Z" fill={c.surface2} stroke={c.border} strokeWidth={sw} />
      <path d="M100 176 L100 184 L172 142 L172 134 Z" fill={c.bg2} stroke={c.border} strokeWidth={sw} />
      {box(70, 128 + fall(d1), 40, 40, 30, c.primary, "a")}
      {box(130, 124 + fall(d2), 36, 36, 26, c.accent, "b")}
      {box(100, 100 + fall(d3), 34, 34, 26, c.gradB, "c")}
    </g>
  );
}

