export default function WarehousePacking({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const cv = p.conveyor ?? 0;
  const lid = p.lid ?? 0;
  // iso helpers: x axis goes right-down (cos30, sin30), y axis left-down
  const X = 0.866, Y = 0.5;
  const P = (x: number, y: number, z: number) => `${(100 + (x - y) * X).toFixed(1)} ${(100 + (x + y) * Y - z).toFixed(1)}`;
  const box = (x: number, y: number, z: number, w: number, d: number, h: number, col: string) => (
    <g stroke={c.border} strokeWidth={sw} strokeLinejoin="round" strokeLinecap="round">
      <path d={`M${P(x, y, z + h)} L${P(x + w, y, z + h)} L${P(x + w, y + d, z + h)} L${P(x, y + d, z + h)} Z`} fill={col} fillOpacity={1} />
      <path d={`M${P(x, y + d, z + h)} L${P(x + w, y + d, z + h)} L${P(x + w, y + d, z)} L${P(x, y + d, z)} Z`} fill={col} fillOpacity={0.75} />
      <path d={`M${P(x + w, y, z + h)} L${P(x + w, y + d, z + h)} L${P(x + w, y + d, z)} L${P(x + w, y, z)} Z`} fill={col} fillOpacity={0.5} />
    </g>
  );
  const px = -20 + cv * 50;
  const flap = (1 - lid) * 50;
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <g transform="translate(100 100) scale(0.6) translate(-100 -100)">
      <path d={`M${P(-70, -70, 0)} L${P(90, -70, 0)} L${P(90, 90, 0)} L${P(-70, 90, 0)} Z`} fill={c.surface2} fillOpacity={0.5} stroke={c.border} strokeWidth={sw} transform="translate(0 28)" />
      <g transform="translate(0 28)">
        {/* stacked shelves boxes back */}
        {box(-65, -65, 0, 30, 30, 22, c.surface)}
        {box(-65, -65, 22, 30, 30, 18, c.accent)}
        {box(-30, -65, 0, 26, 30, 18, c.accent)}
        {/* conveyor */}
        {box(-60, -12, 0, 140, 34, 8, c.primary)}
        {box(-60, -12, 8, 140, 34, 6, c.surface)}
        {[0, 1, 2, 3, 4, 5, 6].map(i => (
          <path key={i} d={`M${P(-50 + i * 20 + (cv * 20) % 20, -12 + 34, 14)} L${P(-50 + i * 20 + (cv * 20) % 20, -12, 14)}`} stroke={c.border} strokeWidth={sw} opacity={0.6} />
        ))}
        {/* parcel */}
        {box(px - 10, -2, 14, 34, 24, 22, c.gradA)}
        {/* tape */}
        <path d={`M${P(px + 7, -2, 36)} L${P(px + 7, 22, 36)}`} stroke={c.onPrimary} strokeWidth={sw} opacity={lid} />
        {/* flaps */}
        <g transform={`translate(0 ${-flap * 0.3})`} opacity={1}>
          <path d={`M${P(px - 10, -2, 36)} L${P(px + 24, -2, 36)} L${P(px + 24, -2 + 12 * lid, 36 + flap * 0.8)} L${P(px - 10, -2 + 0, 36 + flap * 0.8)} Z`} fill={c.gradA} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
        </g>
        {/* tape dispenser arm */}
        {box(30, -30, 0, 8, 8, 60, c.surface)}
        {box(8, -30, 52, 30, 8, 8, c.primary)}
      </g>
    </g>
    </g>
  );
}

