export default function DeliveryRoute({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const road = p.road ?? 0;
  const van = p.van ?? 0;
  // route polyline in iso space: A(30,120) -> B(80,145) -> C(130,120) -> D(150,110)
  const pts = [[28, 118], [78, 143], [128, 118], [150, 107]];
  const lens = [Math.hypot(50, 25), Math.hypot(50, 25), Math.hypot(22, 11)];
  const total = lens[0] + lens[1] + lens[2];
  let d = van * total;
  let vx = pts[0][0], vy = pts[0][1];
  for (let i = 0; i < 3; i++) {
    if (d <= lens[i] || i === 2) {
      const t = Math.min(1, d / lens[i]);
      vx = pts[i][0] + (pts[i + 1][0] - pts[i][0]) * t;
      vy = pts[i][1] + (pts[i + 1][1] - pts[i][1]) * t;
      break;
    }
    d -= lens[i];
  }
  const box = (x: number, y: number, w: number, h: number, role: string) => {
    const a = w * 0.866, b = w * 0.5;
    return (
      <g stroke={c.border} strokeWidth={sw} strokeLinejoin="round" strokeLinecap="round">
        <path d={`M${x - a} ${y - h + b} L${x} ${y - h + 2 * b} L${x} ${y + 2 * b} L${x - a} ${y + b} Z`} fill={role} fillOpacity={0.75} />
        <path d={`M${x} ${y - h + 2 * b} L${x + a} ${y - h + b} L${x + a} ${y + b} L${x} ${y + 2 * b} Z`} fill={role} fillOpacity={0.5} />
        <path d={`M${x} ${y - h} L${x + a} ${y - h + b} L${x} ${y - h + 2 * b} L${x - a} ${y - h + b} Z`} fill={role} fillOpacity={1} />
      </g>
    );
  };
  const path = `M${pts[0][0]} ${pts[0][1]} L${pts[1][0]} ${pts[1][1]} L${pts[2][0]} ${pts[2][1]} L${pts[3][0]} ${pts[3][1]}`;
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <path d="M100 168 L184 126 L100 84 L16 126 Z" fill={c.surface} stroke={c.border} strokeWidth={sw} />
      <defs><clipPath id={`${uid}-rc`}><rect x={20} y={0} width={Math.max(0.01, 140 * road)} height={200} /></clipPath></defs>
      <path d="M28 111 L78 136 L128 111 L150 100 L150 114 L128 125 L78 150 L28 125 Z" fill={c.surface2} stroke={c.border} strokeWidth={sw} clipPath={`url(#${uid}-rc)`} />
      <path d={path} fill="none" stroke={c.accent} strokeWidth={sw} pathLength={1} strokeDasharray="0.03 0.03" strokeDashoffset={1 - road} opacity={road > 0.02 ? 1 : 0} />
      {box(28, 100, 10, 16, c.accent)}
      {box(78, 124, 10, 12, c.accent)}
      {box(150, 72, 20, 26, c.primary)}
      <path d="M130 72 L150 60 L170 72" fill="none" stroke={c.border} strokeWidth={sw} opacity={0} />
      <g transform={`translate(${vx} ${vy})`}>
        {box(0, -14, 9, 8, c.surface2)}
        {box(8, -16, 5, 5, c.primary)}
      </g>
    </g>
  );
}

