export default function ConfirmPhone({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const k = p.checks ?? 0;
  const rows = [0, 1, 2].map((i) => {
    const t = Math.max(0, Math.min(1, k * 3 - i));
    return { y: 74 + i * 24, t };
  });
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <ellipse cx={100} cy={176} rx={74} ry={12} fill={c.black} opacity={0.1} />
      {/* phone slab: iso box */}
      <path d="M40 60 L40 150 L74 168 L74 78 Z" fill={c.primary} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
      <path d="M74 78 L74 168 L124 140 L124 50 Z" fill={c.primary} fillOpacity={0.5} stroke={c.border} strokeWidth={sw} />
      <path d="M40 60 L90 32 L124 50 L74 78 Z" fill={c.primary} fillOpacity={1} stroke={c.border} strokeWidth={sw} />
      {/* screen on right face */}
      <path d="M79 84 L79 160 L119 137 L119 61 Z" fill={c.surface} stroke={c.border} strokeWidth={sw} />
      {rows.map((r, i) => {
        const x = 84, yy = r.y - i * 0;
        const oy = 70 + i * 22 - ((x - 79) * 0.575);
        return (
          <g key={i}>
            <path d={`M${x + 16} ${oy + 18 - 0} L${x + 34} ${oy + 8}`} stroke={c.textMuted} strokeWidth={sw} opacity={0.6} />
            <g transform={`translate(${x + 4} ${oy + 20}) scale(${0.2 + 0.8 * r.t})`} opacity={r.t > 0 ? 1 : 0}>
              <circle cx={0} cy={0} r={6} fill={c.accent} stroke={c.border} strokeWidth={sw} />
              <path d="M-3 0 L-1 2.5 L3 -2" fill="none" stroke={c.onPrimary} strokeWidth={sw} />
            </g>
          </g>
        );
      })}
      {/* headset on iso pedestal */}
      <path d="M130 156 L130 166 L152 178 L152 168 Z" fill={c.surface2} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
      <path d="M152 168 L152 178 L176 165 L176 155 Z" fill={c.surface2} fillOpacity={0.5} stroke={c.border} strokeWidth={sw} />
      <path d="M130 156 L154 143 L176 155 L152 168 Z" fill={c.surface2} stroke={c.border} strokeWidth={sw} />
      <path d="M136 124 C136 94 172 94 172 124" fill="none" stroke={c.accent} strokeWidth={sw} />
      <path d="M132 120 L140 120 L140 140 L132 140 Z" fill={c.accent} fillOpacity={0.75} stroke={c.border} strokeWidth={sw} />
      <path d="M168 120 L176 120 L176 140 L168 140 Z" fill={c.accent} stroke={c.border} strokeWidth={sw} />
      <path d="M172 140 C172 152 160 152 154 150" fill="none" stroke={c.border} strokeWidth={sw} />
      <circle cx={153} cy={150} r={3} fill={c.accent} stroke={c.border} strokeWidth={sw} />
    </g>
  );
}

