export default function PhoneWithBug({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const f = p.crash_flash ?? 0;
  const g = p.screen_glow ?? 0;
  const pulse = 0.55 + 0.45 * Math.sin(f * Math.PI * 5);
  const bugOp = f > 0 ? pulse : 1;
  const s = 1 + f * 0.12;
  const st = { fill: "none", strokeWidth: sw, strokeLinecap: "round" as const, strokeLinejoin: "round" as const };
  const phone = (
    <g>
      <rect x={52} y={20} width={96} height={160} rx={16} stroke={c.primary} {...st} />
      <rect x={60} y={36} width={80} height={128} rx={6} stroke={c.primary} {...st} opacity={0.7} />
      <path d="M90 28 L110 28" stroke={c.primary} {...st} />
      <path d="M92 172 L108 172" stroke={c.primary} {...st} />
    </g>
  );
  const bug = (
    <g transform={`translate(100 100) scale(${s}) translate(-100 -100)`} opacity={bugOp} stroke={c.accent} {...st}>
      <ellipse cx={100} cy={106} rx={13} ry={17} />
      <circle cx={100} cy={84} r={7} />
      <path d="M100 90 L100 123 M87 100 L74 94 M87 108 L72 108 M88 117 L76 124 M113 100 L126 94 M113 108 L128 108 M112 117 L124 124 M95 78 L91 71 M105 78 L109 71" />
    </g>
  );
  const crack = (
    <path d="M140 36 L120 70 L132 80 L108 112 L116 120 L96 164 M120 70 L98 66 M108 112 L80 120" stroke={c.accent} {...st} pathLength={1} strokeDasharray={1} strokeDashoffset={1 - f} opacity={f > 0.01 ? 1 : 0} />
  );
  return (
    <g>
      <defs>
        <filter id={`${uid}-n`} x="-30%" y="-30%" width="160%" height="160%">
          <feGaussianBlur stdDeviation={3} result="b" />
          <feMerge><feMergeNode in="b" /><feMergeNode in="SourceGraphic" /></feMerge>
        </filter>
        <radialGradient id={`${uid}-r`}>
          <stop offset="0" stopColor={c.glowA} stopOpacity={0.8} />
          <stop offset="1" stopColor={c.glowB} stopOpacity={0.15} />
        </radialGradient>
      </defs>
      <rect x={60} y={36} width={80} height={128} rx={6} fill={`url(#${uid}-r)`} opacity={g * 0.6} />
      <g filter={`url(#${uid}-n)`}>
        {phone}
        <rect x={60} y={36} width={80} height={128} rx={6} stroke={c.glowA} {...st} opacity={g} />
        {bug}
        {crack}
      </g>
    </g>
  );
}

