export default function ContextNodes({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const n = p.nodes ?? 0;
  const l = p.links ?? 0;
  const pts = [[100, 100], [50, 52], [152, 50], [46, 150], [154, 148]];
  const sc = (i: number) => {
    const t = Math.max(0, Math.min(1, n * 5 - (i - 0)));
    return 0.4 + 0.6 * t;
  };
  const op = (i: number) => 0.35 + 0.65 * Math.max(0, Math.min(1, n * 5 - i));
  const links = [[0, 1], [0, 2], [0, 3], [0, 4]];
  const glow = `url(#${uid}-f)`;
  const shapes = (i: number) => {
    if (i === 0) return <><circle r={20} /><circle r={7} /></>;
    if (i === 1) return <><rect x={-16} y={-16} width={32} height={32} rx={6} /><path d="M-8 -5 H8 M-8 2 H4 M-8 8 H8" /></>;
    if (i === 2) return <><rect x={-11} y={-18} width={22} height={36} rx={5} /><path d="M-3 13 H3" /></>;
    if (i === 3) return <><circle r={16} /><path d="M-8 0 L-2 6 L9 -6" /></>;
    return <path d="M-18 -14 H18 L7 0 V15 H-7 V0 Z" />;
  };
  const render = (stroke: string) => (
    <g fill="none" stroke={stroke} strokeWidth={sw} strokeLinecap="round" strokeLinejoin="round">
      {links.map(([a, b], i) => {
        const [x1, y1] = pts[a], [x2, y2] = pts[b];
        const t = Math.max(0, Math.min(1, l * 4 - i));
