      })}
      {pts.map(([x, y], i) => (
        <g key={i} transform={`translate(${x} ${y}) scale(${sc(i)})`} opacity={op(i)} stroke={i === 0 ? c.accent : c.primary}>
          {shapes(i)}
        </g>
      ))}
    </g>
  );
  return (
