export default function ParcelBox({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const lid = p.lid ?? 0;
  const open = (1 - lid) * 62;
  const tape = Math.max(0, Math.min(1, (lid - 0.6) / 0.4));
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      {/* table */}
      <rect x={20} y={150} width={160} height={12} rx={4} fill={c.surface2} />
      <rect x={32} y={162} width={10} height={26} fill={c.surface2} />
      <rect x={158} y={162} width={10} height={26} fill={c.surface2} />
      <ellipse cx={104} cy={150} rx={70} ry={5} fill={c.black} opacity={0.15} />
      {/* box body */}
      <rect x={42} y={92} width={116} height={58} fill={c.surface} />
      <rect x={42} y={92} width={116} height={58} fill={c.black} opacity={0.06} />
      <rect x={42} y={92} width={22} height={58} fill={c.black} opacity={0.08} />
      <rect x={90} y={92} width={20} height={58} fill={c.accent} opacity={tape} />
      {/* back flaps */}
      <g transform={`rotate(${-open} 42 92)`}>
        <rect x={42} y={76} width={58} height={16} fill={c.surface2} />
      </g>
      <g transform={`rotate(${open} 158 92)`}>
        <rect x={100} y={76} width={58} height={16} fill={c.surface2} />
      </g>
      {/* closed lid top */}
      <rect x={42} y={84} width={116} height={10} fill={c.surface2} opacity={lid} />
      <rect x={90} y={84} width={20} height={10} fill={c.accent} opacity={tape} />
      <rect x={54} y={124} width={22} height={4} rx={2} fill={c.primary} opacity={0.6} />
      <rect x={54} y={133} width={34} height={4} rx={2} fill={c.primary} opacity={0.3} />
    </g>
  );
}

