export default function StockedShelves({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const b = p.boxes ?? 0;
  const cols = [c.primary, c.accent, c.surface2, c.gradA, c.gradB];
  const rows = [58, 100, 142];
  const grad = (i: number) => (
    <radialGradient key={i} id={`${uid}-g${i}`} cx="0.3" cy="0.25" r="0.9">
      <stop offset="0" stopColor={c.white} stopOpacity={0.6} />
      <stop offset="1" stopColor={cols[i]} />
    </radialGradient>
  );
  const items: any[] = [];
  rows.forEach((y, r) => {
    const t = Math.max(0, Math.min(1, b * 3 - (2 - r)));
    [0, 1, 2].forEach((k) => {
      const tt = Math.max(0, Math.min(1, t * 3 - k));
      const w = 30 + ((r + k) % 2) * 6;
      const h = 24 + ((r * 2 + k) % 3) * 4;
      const x = 38 + k * 44 + (44 - w) / 2 - 6;
      const drop = (1 - tt) * -30;
      items.push(
        <g key={`${r}${k}`} opacity={tt} transform={`translate(0 ${drop})`}>
          <rect x={x} y={y - h} width={w} height={h} rx={7} fill={`url(#${uid}-g${(r + k * 2) % 5})`} stroke={c.border} strokeWidth={sw} />
          <path d={`M${x + 7} ${y - h + 8} L${x + w - 9} ${y - h + 8}`} stroke={c.white} opacity={0.7} strokeWidth={sw} />
        </g>
      );
    });
  });
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <defs>{[0, 1, 2, 3, 4].map(grad)}
        <radialGradient id={`${uid}-s`} cx="0.3" cy="0.2" r="1">
          <stop offset="0" stopColor={c.white} stopOpacity={0.5} />
          <stop offset="1" stopColor={c.surface} />
        </radialGradient>
      </defs>
      <ellipse cx={100} cy={176} rx={74} ry={8} fill={c.black} opacity={0.15} />
      <rect x={22} y={26} width={10} height={148} rx={5} fill={`url(#${uid}-s)`} stroke={c.border} strokeWidth={sw} />
      <rect x={168} y={26} width={10} height={148} rx={5} fill={`url(#${uid}-s)`} stroke={c.border} strokeWidth={sw} />
      {rows.map((y) => (
        <rect key={y} x={24} y={y} width={152} height={9} rx={4.5} fill={`url(#${uid}-s)`} stroke={c.border} strokeWidth={sw} />
      ))}
      {items}
    </g>
  );
}

