export default function DeliveryTruck({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const w = p.wheels ?? 0;
  const rot = w * 270;
  const dx = w * 8;
  const grad = (id: string, col: string) => (
    <radialGradient id={`${uid}-${id}`} cx="0.3" cy="0.25" r="0.9">
      <stop offset="0" stopColor={c.white} stopOpacity={0.6} />
      <stop offset="1" stopColor={col} />
    </radialGradient>
  );
  const wheel = (cx: number) => (
    <g transform={`translate(${cx} 148)`}>
      <circle r={17} fill={`url(#${uid}-k)`} stroke={c.border} strokeWidth={sw} />
      <g transform={`rotate(${rot})`}>
        <circle r={8} fill={`url(#${uid}-s)`} stroke={c.border} strokeWidth={sw} />
        <path d="M0 -6 L0 6 M-6 0 L6 0" stroke={c.border} strokeWidth={sw} />
        <circle cx={0} cy={-12} r={3} fill={c.accent} />
      </g>
    </g>
  );
  return (
    <g strokeLinecap="round" strokeLinejoin="round" transform={`translate(${-dx} 0)`}>
      <defs>
        {grad("b", c.primary)}
        {grad("s", c.surface)}
        {grad("k", c.text)}
        {grad("a", c.accent)}
        {grad("g", c.gradA)}
      </defs>
      <ellipse cx={100} cy={170} rx={76} ry={8} fill={c.black} opacity={0.15} />
      <rect x={22} y={62} width={96} height={90} rx={16} fill={`url(#${uid}-s)`} stroke={c.border} strokeWidth={sw} />
      <path d="M118 84 L152 84 Q164 84 170 98 L178 120 Q180 126 180 132 L180 146 Q180 152 174 152 L118 152 Z" fill={`url(#${uid}-b)`} stroke={c.border} strokeWidth={sw} />
      <path d="M128 94 L150 94 Q155 94 158 100 L164 114 L128 114 Z" fill={`url(#${uid}-g)`} stroke={c.border} strokeWidth={sw} />
      <rect x={34} y={74} width={40} height={10} rx={5} fill={c.primary} opacity={0.3} />
      <g transform="translate(70 38)">
        <rect x={-30} y={4} width={60} height={26} rx={10} fill={`url(#${uid}-a)`} stroke={c.border} strokeWidth={sw} />
        <path d="M-6 17 L6 17" stroke={c.onPrimary} strokeWidth={sw} />
        <rect x={-6} y={0} width={12} height={34} rx={5} fill={c.primary} opacity={0.6} />
        <circle cx={-18} cy={17} r={3} fill={c.white} opacity={0.6} />
      </g>
      <rect x={172} y={128} width={8} height={8} rx={3} fill={c.accent} />
      {wheel(56)}
      {wheel(148)}
    </g>
  );
}

