export default function ProfitChart({ p, c, sw, uid }: { p: Record<string, number>; c: Record<string, string>; sw: number; uid: string }) {
  const b = p.bars ?? 0;
  const g = (id: string, col: string) => (
    <radialGradient id={`${uid}-${id}`} cx="0.3" cy="0.25" r="0.9">
      <stop offset="0" stopColor={c.white} stopOpacity={0.7} />
      <stop offset="1" stopColor={col} />
    </radialGradient>
  );
  const base = 160;
  const hs = [36, 62, 92];
  const xs = [48, 90, 132];
  const fills = ["a", "b", "a"];
  const top = (i: number) => base - hs[i] * (0.15 + 0.85 * b);
  const ax = (i: number) => xs[i] + 14;
  return (
    <g strokeLinecap="round" strokeLinejoin="round">
      <defs>
        {g("a", c.primary)}
        {g("b", c.accent)}
        {g("c", c.surface)}
        {g("d", c.gradA)}
      </defs>
      <ellipse cx={100} cy={172} rx={74} ry={9} fill={c.black} opacity={0.15} />
      <rect x={26} y={150} width={148} height={20} rx={10} fill={`url(#${uid}-c)`} stroke={c.border} strokeWidth={sw} />
      {xs.map((x, i) => (
        <rect key={i} x={x} y={top(i)} width={28} height={base - top(i) + 4} rx={10} fill={`url(#${uid}-${fills[i]})`} stroke={c.border} strokeWidth={sw} />
      ))}
      <path d={`M${ax(0)} ${top(0) - 14} L${ax(1)} ${top(1) - 14} L${ax(2)} ${top(2) - 18}`} fill="none" stroke={c.accent} strokeWidth={sw} />
      <path d={`M${ax(2) - 10} ${top(2) - 20} L${ax(2)} ${top(2) - 18} L${ax(2) - 4} ${top(2) - 8}`} fill="none" stroke={c.accent} strokeWidth={sw} />
      <g transform={`translate(0 ${-(1 - b) * 0})`}>
        <circle cx={160} cy={132} r={19} fill={`url(#${uid}-d)`} stroke={c.border} strokeWidth={sw} />
        <circle cx={160} cy={132} r={11} fill="none" stroke={c.white} strokeWidth={sw} opacity={0.6} />
        <path d="M156 132 L164 132" stroke={c.white} strokeWidth={sw} />
      </g>
    </g>
  );
}

